import requests

BASE_URL = "http://localhost:3011"
SPECIFICATIONS_ENDPOINT = f"{BASE_URL}/api/specifications"
TIMEOUT = 30

def test_create_specification_with_invalid_dimensions():
    # Examples of invalid payloads for specifications (invalid dimensions and malformed)
    invalid_payloads = [
        # Negative dimensions
        {
            "floor": "First Floor",
            "rooms": [
                {"name": "Room A", "length": -5, "width": 4, "height": 3}
            ]
        },
        # Missing required room fields (malformed)
        {
            "floor": "Second Floor",
            "rooms": [
                {"name": "Room B", "length": 5}  # Missing width and height
            ]
        },
        # Dimensions as strings instead of numbers
        {
            "floor": "Third Floor",
            "rooms": [
                {"name": "Room C", "length": "five", "width": "four", "height": "three"}
            ]
        },
        # Completely malformed payload (not a dict)
        "this is not a dict",
        # Empty payload
        {}
    ]

    headers = {"Content-Type": "application/json"}

    for payload in invalid_payloads:
        try:
            if isinstance(payload, str):
                # Send as raw string data for malformed payload test
                response = requests.post(
                    SPECIFICATIONS_ENDPOINT, data=payload, headers=headers, timeout=TIMEOUT
                )
            else:
                response = requests.post(
                    SPECIFICATIONS_ENDPOINT, json=payload, headers=headers, timeout=TIMEOUT
                )
        except requests.RequestException as e:
            assert False, f"Request failed with exception: {e}"

        assert response.status_code == 400, (
            f"Expected status code 400 for payload {payload}, "
            f"but got {response.status_code} with response: {response.text}"
        )
        try:
            resp_json = response.json()
        except ValueError:
            assert False, f"Response is not valid JSON for payload {payload}: {response.text}"

        # Expect validation errors in response body (exact field names may vary)
        assert "errors" in resp_json or "message" in resp_json or "validation" in resp_json, (
            f"Expected validation error details in response for payload {payload}, got: {resp_json}"
        )

test_create_specification_with_invalid_dimensions()

import requests

BASE_URL = "http://localhost:3011"
LOGIN_URL = f"{BASE_URL}/api/auth/login"
SPECIFICATIONS_URL = f"{BASE_URL}/api/specifications"

# Provide valid credentials for authentication
EMAIL = "testuser@example.com"
PASSWORD = "testpassword"

def authenticate():
    try:
        response = requests.post(
            LOGIN_URL,
            json={"email": EMAIL, "password": PASSWORD},
            timeout=30
        )
        response.raise_for_status()
        return response.json().get("token")
    except Exception as e:
        raise RuntimeError(f"Authentication failed: {e}")

def create_valid_specification(headers):
    valid_spec_payload = {
        "floor": 1,
        "rooms": [
            {
                "name": "Room A",
                "length": 5.0,
                "width": 4.0,
                "height": 3.0
            }
        ]
    }
    resp = requests.post(SPECIFICATIONS_URL, json=valid_spec_payload, headers=headers, timeout=30)
    resp.raise_for_status()
    return resp.json().get("id")

def delete_specification(spec_id, headers):
    requests.delete(f"{SPECIFICATIONS_URL}/{spec_id}", headers=headers, timeout=30)

def test_update_specification_with_unsupported_data():
    token = authenticate()
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json"
    }

    spec_id = None
    try:
        spec_id = create_valid_specification(headers)

        # Unsupported room data payload (e.g. negative dimension or unexpected fields)
        unsupported_payload = {
            "floor": 1,
            "rooms": [
                {
                    "name": "Invalid Room",
                    "length": -5,       # unsupported negative dimension
                    "width": 4,
                    "height": 3,
                    "extraField": "unsupported"  # unsupported additional field
                }
            ]
        }

        update_resp = requests.put(f"{SPECIFICATIONS_URL}/{spec_id}", json=unsupported_payload, headers=headers, timeout=30)

        # Assert response status 422 for unsupported room data
        assert update_resp.status_code == 422, f"Expected 422 status but got {update_resp.status_code}"

        # Assert response body contains calculation or business-rule error indication
        json_resp = update_resp.json()
        error_messages = [
            "calculation error",
            "business-rule error",
            "unsupported",
            "invalid",
            "dimension"
        ]
        error_found = any(
            error_key in str(json_resp).lower() for error_key in error_messages
        )
        assert error_found, f"Expected calculation or business-rule error message in response but got: {json_resp}"

    finally:
        if spec_id:
            delete_specification(spec_id, headers)

test_update_specification_with_unsupported_data()
